package net.civeira.phylax.feature.access.oauthclient.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.access.oauthclient.domain.OauthClient;
import net.civeira.phylax.feature.access.oauthclient.domain.valueobject.FrontchannelLogoutSessionRequiredVO;

class FrontchannelLogoutSessionRequiredValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of frontchannel logout session required of oauth client")
  void test_frontchannel_logout_session_required_value_holder_assign_plain_value() {
    Object holder = new Object();
    FrontchannelLogoutSessionRequiredValueHolder<Object> value =
        new FrontchannelLogoutSessionRequiredValueHolder<>(holder);
    Assertions.assertSame(holder, value.frontchannelLogoutSessionRequired(true),
        "Setters must return the holder");
    Assertions.assertTrue(value.getFrontchannelLogoutSessionRequiredValue().isPresent(),
        "The plain value must be stored");
    Assertions.assertEquals(true, value.getFrontchannelLogoutSessionRequired().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.frontchannelLogoutSessionRequiredNull(),
        "Setters must return the holder");
    Assertions.assertTrue(value.getFrontchannelLogoutSessionRequiredValue().isPresent(),
        "A null value object must be stored");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of frontchannel logout session required of oauth client")
  void test_frontchannel_logout_session_required_value_holder_assign_value_object() {
    Object holder = new Object();
    FrontchannelLogoutSessionRequiredValueHolder<Object> value =
        new FrontchannelLogoutSessionRequiredValueHolder<>(holder);
    FrontchannelLogoutSessionRequiredVO vo = FrontchannelLogoutSessionRequiredVO.from(true);
    Assertions.assertFalse(value.getFrontchannelLogoutSessionRequiredValue().isPresent(),
        "A new holder must be empty");
    Assertions.assertSame(holder, value.frontchannelLogoutSessionRequired(vo),
        "Setters must return the holder");
    Assertions.assertSame(vo, value.getFrontchannelLogoutSessionRequiredValue().orElseThrow());
    Assertions.assertSame(holder, value.frontchannelLogoutSessionRequired(Optional.empty()));
    Assertions.assertFalse(value.getFrontchannelLogoutSessionRequiredValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.frontchannelLogoutSessionRequired(Optional.of(vo)));
    Assertions.assertSame(vo, value.getFrontchannelLogoutSessionRequiredValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of frontchannel logout session required of oauth client against the original")
  void test_frontchannel_logout_session_required_value_holder_read() {
    Object holder = new Object();
    FrontchannelLogoutSessionRequiredValueHolder<Object> value =
        new FrontchannelLogoutSessionRequiredValueHolder<>(holder);
    FrontchannelLogoutSessionRequiredVO vo = FrontchannelLogoutSessionRequiredVO.from(true);
    FrontchannelLogoutSessionRequiredVO other = FrontchannelLogoutSessionRequiredVO.from(true);
    OauthClient original = Mockito.mock(OauthClient.class);
    Mockito.when(original.getFrontchannelLogoutSessionRequiredValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other,
        value.readFrontchannelLogoutSessionRequired(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readFrontchannelLogoutSessionRequired(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.frontchannelLogoutSessionRequired(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo,
        value.readFrontchannelLogoutSessionRequired(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo,
        value.readFrontchannelLogoutSessionRequired(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of frontchannel logout session required of oauth client")
  void test_frontchannel_logout_session_required_value_holder_unset() {
    Object holder = new Object();
    FrontchannelLogoutSessionRequiredValueHolder<Object> value =
        new FrontchannelLogoutSessionRequiredValueHolder<>(holder);
    FrontchannelLogoutSessionRequiredVO vo = FrontchannelLogoutSessionRequiredVO.from(true);
    value.frontchannelLogoutSessionRequired(vo);
    Assertions.assertSame(holder, value.unsetFrontchannelLogoutSessionRequiredIfMatches(
        "frontchannelLogoutSessionRequired_other"));
    Assertions.assertTrue(value.getFrontchannelLogoutSessionRequiredValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder,
        value.unsetFrontchannelLogoutSessionRequiredIfMatches("frontchannelLogoutSessionRequired"));
    Assertions.assertFalse(value.getFrontchannelLogoutSessionRequiredValue().isPresent(),
        "The field name must clear the value");
    value.frontchannelLogoutSessionRequired(vo);
    Assertions.assertSame(holder, value.unsetFrontchannelLogoutSessionRequired());
    Assertions.assertFalse(value.getFrontchannelLogoutSessionRequiredValue().isPresent(),
        "Unset must clear the value");
  }
}
